package com.pantrypal.dao;

import com.pantrypal.model.User;
import java.util.List;
import java.util.Optional;
public class UserDAO extends BaseDAO {
    // =====================================================================
    // CREATE
    // =====================================================================
    /**
     * Inserts a User. Because of cascade = ALL, every PantryItem already added
     * to user.getPantryItems() is inserted too, with the FK filled in.
     *
     * @return the AUTO_INCREMENT id generated by MySQL
     */
    public Integer createUser(User user) {
        return executeInTransaction(session -> {
            session.persist(user);          
            return user.getId();
        });
    }
    
    // =====================================================================
    // READ
    // =====================================================================
    /** Finds one User AND loads their pantry items in the same query. */
    public Optional<User> findById(Integer id) {
        return executeInTransaction(session -> session.createQuery(
                "select u from User u left join fetch u.pantryItems where u.id = :id", User.class)
                .setParameter("id", id)
                .uniqueResultOptional());
    }
    
    public Optional<User> findByEmail(String email) {
        return executeInTransaction(session -> session.createQuery(
                "from User u where u.email = :email", User.class)
                .setParameter("email", email)
                .uniqueResultOptional());
    }
    
    public List<User> findAll() {
        return executeInTransaction(session ->
                session.createQuery("from User u order by u.id", User.class).getResultList());
    }
    
    // =====================================================================
    // UPDATE
    // =====================================================================
    public void updateSettings(Integer userId, boolean notifications, boolean purchaseSuggestions) {
        runInTransaction(session -> {
            User user = session.get(User.class, userId);
            if (user == null) {
                throw new DataAccessException("No user with id " + userId);
            }
            user.setNotificationsEnabled(notifications);
            user.setAllowPurchaseSuggestions(purchaseSuggestions);
        });
    }
    
    // =====================================================================
    // DELETE
    // =====================================================================
   
    public boolean deleteUser(Integer userId) {
        return executeInTransaction(session -> {
            User user = session.get(User.class, userId);
            if (user == null) {
                return false;
            }
            session.remove(user);
            return true;
        });
    }
}